/* Browser preview integration. No external mail is sent from this workspace. */
(() => {
 'use strict';
 const H=Helpdesk;
 window.helpdeskReady=true;
 H.normalize(state);
 try{save();}catch{toast('Helpdesk migration could not be saved. Free browser storage before continuing.');}
 let queue='active',search='',clientFilter='',ownerFilter='',page=1,externalChange=false;
 const optionsHtml=(items,value)=>items.map(item=>{const [v,label]=Array.isArray(item)?item:[item,item];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`;}).join('');
 const input=(name,label,value='',type='text',required=false)=>`<div class="field"><label for="hd-${name}">${label}${required?' *':''}</label><input id="hd-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`;
 const choice=(name,label,items,value)=>`<div class="field"><label for="hd-${name}">${label}</label><select id="hd-${name}" name="${name}">${optionsHtml(items,value)}</select></div>`;
 const area=(name,label,value='',required=false)=>`<div class="field"><label for="hd-${name}">${label}${required?' *':''}</label><textarea id="hd-${name}" name="${name}" maxlength="10000" ${required?'required':''}>${esc(value)}</textarea></div>`;
 const ownerOptions=()=>[['','Unassigned'],...state.supportUsers.filter(u=>u.active).map(u=>[u.id,`${u.name} · ${u.team}`])];
 const date=value=>value?new Date(value).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}):'Not recorded';
 const scopeLabel=t=>t.scope==='Whole client'?`Whole client${t.productId?' · deployed locations':''}`:t.branchIds.map(id=>nameOf('branches',id)).join(', ')||'No branch';
 const errorHtml='<p class="form-error" role="alert"></p>';
 function commit(change){
  const latest=JSON.parse(localStorage.getItem(STORE_KEY)||'null');
  if(externalChange||(latest?.helpdesk?.changeVersion||0)>(state.helpdesk.changeVersion||0))throw new Error('Another tab changed this workspace. Reload this page before saving, so those changes are preserved.');
  const before=JSON.stringify(state);
  try{const result=change();if(JSON.stringify(state)!==before){state.helpdesk.changeVersion=(state.helpdesk.changeVersion||0)+1;save();}return result;}catch(error){state=JSON.parse(before);if(error.name==='QuotaExceededError')throw new Error('Browser storage is full. The change was not saved. Remove a local attachment and try again.');throw error;}
 }
 function feedback(error,form){const target=form?.querySelector('.form-error')||$('#modal-root .form-error');if(target)target.textContent=error.message;else toast(error.message);}
 function refresh(message){$('#modal-root').innerHTML='';render();if(message)toast(message);}
 function openCase(id){selectedTicketId=id;setView('ticketDetail');}
 function serviceTick(){try{commit(()=>H.escalate(state));}catch(error){toast(error.message);}}
 function statusPill(t){return tag(t.archivedAt?'Archived':t.status);}
 function clockText(t){const d=H.deadlines(t);return t.archivedAt?'History retained':!H.active(t)?'Tracking stopped':d.responseLate?'Response overdue':d.resolutionLate?'Resolution overdue':d.paused?'Waiting on client · resolution paused':`Resolution ${date(d.resolutionDue)}`;}

 renderHelpdesk=function(){
  serviceTick();
  const active=state.tickets.filter(H.active),late=active.filter(t=>{const d=H.deadlines(t);return d.responseLate||d.resolutionLate;}),q=search.toLowerCase();
  const rows=state.tickets.filter(t=>(queue==='archived'?!!t.archivedAt:!t.archivedAt&&(queue==='all'||queue==='active'&&H.active(t)||queue==='unassigned'&&H.active(t)&&!t.ownerId||queue==='overdue'&&late.includes(t)||queue==='closed'&&H.terminal.includes(t.status)))&&(!clientFilter||t.clientId===clientFilter)&&(!ownerFilter||t.ownerId===ownerFilter)&&[t.number,t.subject,t.owner,nameOf('clients',t.clientId),scopeLabel(t),nameOf('products',t.productId),t.module].join(' ').toLowerCase().includes(q));
  rows.sort((a,b)=>Number(!!b.escalatedAt)-Number(!!a.escalatedAt)||H.priorities.indexOf(a.priority)-H.priorities.indexOf(b.priority)||String(b.updatedAt).localeCompare(String(a.updatedAt)));
  const pages=Math.max(1,Math.ceil(rows.length/10));page=Math.min(page,pages);
  return `<div class="core-workspace hd-workspace"><div class="core-heading"><div><span class="core-eyebrow">CLIENT SERVICE</span><h1>Helpdesk</h1><p>One case. Every affected branch. A clear next owner.</p></div><div class="hd-actions"><button class="btn" data-hd="settings">Team & service rules</button><button class="btn btn-primary" data-action="add-ticket">${icon('plus')} New case</button></div></div><div class="core-metrics">${coreMetric('Active cases',String(active.length),'Open work across clients','featured')}${coreMetric('Needs assignment',String(active.filter(t=>!t.ownerId).length),'Waiting for a named owner')}${coreMetric('Service targets overdue',String(late.length),'Response or resolution','warning')}${coreMetric('Waiting on client',String(active.filter(t=>t.status==='Waiting on Client').length),'Resolution pauses per policy')}</div><section class="core-panel"><div class="core-panel-heading"><div><h2>Case queue</h2><p>${rows.length} matching cases · ${state.tickets.filter(t=>!!t.archivedAt).length} archived</p></div></div><div class="core-filters"><div class="core-tabs">${[['all','All cases'],['active','Active'],['unassigned','Unassigned'],['closed','Resolved / closed'],['overdue','Overdue'],['archived','Archive']].map(([v,l])=>`<button data-hd="queue" data-value="${v}" aria-pressed="${queue===v}" class="${queue===v?'active':''}">${l}</button>`).join('')}</div><form id="hd-filter-form" class="hd-filters"><input name="search" aria-label="Search cases" value="${esc(search)}" placeholder="Search case, bank, branch or product">${choice('clientFilter','Client',[['','All clients'],...state.clients.map(c=>[c.id,c.name])],clientFilter)}${choice('ownerFilter','Owner',[['','All owners'],...ownerOptions().slice(1)],ownerFilter)}<button class="btn" type="submit">Apply</button></form></div><div class="case-list">${rows.slice((page-1)*10,page*10).map(t=>`<button class="case-row" data-ticket="${esc(t.id)}"><span class="case-row-main"><span class="case-row-top"><strong>${esc(t.subject)}</strong><small>${esc(t.number)}</small></span><span>${esc(nameOf('clients',t.clientId))} · ${esc(scopeLabel(t))}</span><small>${esc(t.productId?nameOf('products',t.productId):'General support')}${t.module?' / '+esc(t.module):''} · ${esc(t.owner||'Unassigned')}</small></span><span class="case-row-meta">${tag(t.priority)} ${statusPill(t)}<small class="${late.includes(t)?'hd-overdue':''}">${esc(clockText(t))}</small>${t.escalatedAt&&H.active(t)?'<small class="hd-overdue">Support lead review</small>':''}</span><span aria-hidden="true">↗</span></button>`).join('')||'<div class="core-empty">No cases match. Adjust the filters or create a case.</div>'}</div><div class="core-pager"><span>Page ${page} of ${pages}</span><div><button data-hd="prev" ${page===1?'disabled':''}>Previous</button><button data-hd="next" ${page===pages?'disabled':''}>Next</button></div></div></section><p class="core-footnote">Local preview · service targets follow your workspace rules. Mail delivery and authenticated team access are not connected.</p></div>`;
 };

 window.openHelpdeskForm=function(id='',prefill={}){
  const t=id?byId('tickets',id):null;if(t&&(t.archivedAt||H.terminal.includes(t.status))){toast('Restore and reopen this case before editing its details.');return;}
  const data=t||{clientId:prefill.clientId||(view==='profile'?selectedClientId:''),scope:prefill.branchId?'Single branch':'Whole client',branchIds:prefill.branchId?[prefill.branchId]:[],priority:prefill.priority||'Medium',category:prefill.category||'Service Request',source:prefill.source||'Internal',coverage:'Unverified',...prefill};
  const c=byId('clients',data.clientId),r=data.requester||{name:c?.contact||'',email:c?.email||'',phone:c?.phone||''};
  const body=`<form id="hd-case-form" data-id="${esc(id)}" data-revision="${t?.revision||1}" data-source-message="${esc(prefill.sourceMessageId||'')}"><h3>Client & affected locations</h3>${choice('clientId','Client *',[['','Choose client'],...state.clients.map(c=>[c.id,c.name])],data.clientId)}<div class="form-grid">${choice('scope','Affected scope',['Single branch','Selected branches','Whole client'],data.scope)}${choice('productId','Product',[['','General support']],data.productId)}</div><div id="hd-branches"></div><div id="hd-module"></div><h3>Request & ownership</h3>${input('subject','Issue summary',data.subject||'','text',true)}${area('description','What happened / expected outcome',data.description||' ',true)}<div class="form-grid">${choice('category','Category',H.categories,data.category)}${choice('priority','Priority',H.priorities,data.priority)}${choice('ownerId','Assigned owner',ownerOptions(),data.ownerId||'')}${choice('source','Source',['Email','Phone','Portal','Internal'],data.source)}</div><h3>Requester</h3>${input('requesterName','Name',r.name,'text',true)}<div class="form-grid">${input('requesterEmail','Email',r.email,'email')}${input('requesterPhone','Phone',r.phone,'tel')}</div><h3>Support coverage</h3><div class="form-grid">${choice('coverage','Coverage',['Unverified','Covered support','Quotation required','Chargeable approved'],data.coverage)}${input('agreementRef','Agreement / approved quotation reference',data.agreementRef||'')}</div><p class="hd-hint">Coverage is verified against the agreement. This case does not create a charge or invoice.</p>${t?area('reason','Reason for correcting these details','',true):area('duplicateReason','Separate issue reason (only if a matching open case exists)')}${errorHtml}</form>`;
  modal(t?'Edit case details':'New support case','Link the issue to the correct client, locations and purchased modules.',body,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit" form="hd-case-form">${t?'Save changes':'Create case'}</button>`);
  $('.modal').classList.add('hd-modal');const form=$('#hd-case-form');if(t)form.elements.clientId.disabled=true;
  form.dataset.product=data.productId||'';form.dataset.module=data.module||'';form.dataset.branches=JSON.stringify(data.branchIds||[]);rebuildContext(form,true);
 };
 function rebuildContext(form,initial=false){
  const clientId=form.elements.clientId.value,scope=form.elements.scope.value,branches=state.branches.filter(b=>b.clientId===clientId);
  const selected=initial?JSON.parse(form.dataset.branches||'[]'):[...form.querySelectorAll('[name="branchIds"]:checked')].map(e=>e.value);
  $('#hd-branches').innerHTML=scope==='Whole client'?'<p class="hd-hint">Includes all current branches. When a product/module is chosen, only its deployed locations are affected. Newly onboarded branches are not added to existing incidents automatically.</p>':`<fieldset class="hd-branch-options"><legend>Affected branches *</legend>${branches.map(b=>`<label><input type="${scope==='Single branch'?'radio':'checkbox'}" name="branchIds" value="${esc(b.id)}" ${selected.includes(b.id)?'checked':''}>${esc(b.name)} <small>${esc(b.city||'')}</small></label>`).join('')||'<p>Add a branch in the client profile first.</p>'}</fieldset>`;
  const chosen=scope==='Whole client'?branches.map(b=>b.id):[...form.querySelectorAll('[name="branchIds"]:checked')].map(e=>e.value);
  const deployments=state.deployments.filter(d=>d.clientId===clientId&&chosen.includes(d.branchId));
  const ids=[...new Set(deployments.map(d=>d.productId))].filter(pid=>scope==='Whole client'||chosen.every(bid=>deployments.some(d=>d.branchId===bid&&d.productId===pid)));
  const product=initial?form.dataset.product:form.elements.productId.value;
  form.elements.productId.innerHTML=optionsHtml([['','General support'],...ids.map(pid=>[pid,nameOf('products',pid)])],product);
  const productId=form.elements.productId.value,ds=deployments.filter(d=>d.productId===productId),mods=[...new Set(ds.flatMap(d=>d.modules||[]))].filter(m=>scope==='Whole client'||ds.every(d=>(d.modules||[]).includes(m)));
  const currentModule=initial?form.dataset.module:form.elements.module?.value||'';
  $('#hd-module').innerHTML=choice('module','Module',[['','All modules / not specified'],...mods],currentModule);
 }
 function formData(form){const data=Object.fromEntries(new FormData(form));return {...data,clientId:form.elements.clientId.value,revision:form.dataset.id?Number(form.dataset.revision):undefined,branchIds:[...form.querySelectorAll('[name="branchIds"]:checked')].map(e=>e.value),requester:{name:data.requesterName,email:data.requesterEmail,phone:data.requesterPhone},sourceMessageId:form.dataset.sourceMessage};}

 renderTicketDetail=function(){
  serviceTick();const t=byId('tickets',selectedTicketId);if(!t)return renderHelpdesk();
  const d=H.deadlines(t),ended=H.terminal.includes(t.status),editable=!t.archivedAt,next=[t.status,...(H.transitions[t.status]||[])];
  const selectedOwner=state.supportUsers.find(u=>u.id===t.ownerId);const owners=ownerOptions();if(t.ownerId&&!selectedOwner?.active)owners.push([t.ownerId,`${t.owner} (inactive — reassign)`]);
  return `<div class="hd-workspace"><button class="profile-back" data-view="helpdesk">← Back to Helpdesk</button><div class="ticket-hero"><div><p class="eyebrow">HELPDESK / ${esc(t.number)}</p><h1>${esc(t.subject)}</h1><p>${esc(nameOf('clients',t.clientId))} · ${esc(scopeLabel(t))}</p></div><div class="hd-actions">${statusPill(t)}${tag(t.priority)}${!ended&&editable?`<button class="btn" data-action="edit-ticket-details" data-id="${esc(t.id)}">Edit details</button>`:''}${t.archivedAt?'<button class="btn" data-hd="restore">Restore case</button>':['Closed','Cancelled'].includes(t.status)?'<button class="btn" data-hd="archive">Archive case</button>':''}</div></div><div class="hd-service-grid"><article class="card"><small>FIRST RESPONSE</small><strong class="${d.responseLate?'hd-overdue':''}">${t.firstResponseAt?'Response recorded':ended?'Not recorded':d.responseLate?'Overdue':'Awaiting response'}</strong><span>${date(t.firstResponseAt||d.responseDue)} IST</span></article><article class="card"><small>RESOLUTION</small><strong class="${d.resolutionLate?'hd-overdue':''}">${t.resolvedAt?'Resolved':t.cancelledAt?'Cancelled':d.paused?'Paused · waiting on client':d.resolutionLate?'Overdue':'In service window'}</strong><span>${date(t.resolvedAt||t.cancelledAt||d.resolutionDue)} IST${d.paused?' · moves while paused':''}</span></article><article class="card"><small>ASSIGNED TO</small><strong>${esc(t.owner||'Unassigned')}</strong><span>${esc(t.team||'Support')}${t.escalatedAt?' · lead review required':''}</span></article></div><div class="hd-detail-grid"><div class="hd-stack"><section class="card hd-section"><div class="card-head"><div><h2>Case context</h2><p>Client, affected locations and support coverage</p></div><button class="row-action" data-profile="${esc(t.clientId)}">Client profile ↗</button></div><dl class="hd-facts"><dt>Requester</dt><dd>${esc(t.requester.name||'Not recorded')}<small>${esc(t.requester.email||t.requester.phone||'Add contact details')}</small></dd><dt>Product / module</dt><dd>${esc(t.productId?nameOf('products',t.productId):'General support')}<small>${esc(t.module||'No specific module')}</small></dd><dt>Affected branches</dt><dd>${t.branchIds.map(id=>esc(nameOf('branches',id))).join(' · ')||'Institution-wide, no branch recorded'}</dd><dt>Category / source</dt><dd>${esc(t.category)} · ${esc(t.source)}</dd><dt>Coverage</dt><dd>${esc(t.coverage)}<small>${esc(t.agreementRef||'Agreement not verified')}</small></dd><dt>Opened</dt><dd>${date(t.createdAt)}</dd></dl><div class="hd-prose">${esc(t.description||t.subject)}</div>${t.resolution?`<div class="hd-resolution"><strong>Resolution</strong><p>${esc(t.resolution)}</p></div>`:''}${t.closure&&t.status==='Closed'?`<p class="hd-hint">Closed: ${esc(t.closure.method)}${t.closure.confirmedBy?' · '+esc(t.closure.confirmedBy):''}</p>`:''}<p class="hd-hint">Service clock: ${t.serviceRules.calendar.start}:00–${t.serviceRules.calendar.end}:00 IST · configured working days. Tracking since ${date(t.trackingStartedAt)}. ${t.serviceRules.pauseOnClient?'Waiting on client pauses resolution only.':'Waiting time counts toward targets.'}</p></section>
  <section class="card hd-section"><div class="card-head"><div><h2>Conversation & notes</h2><p>Internal notes stay separate from recorded client messages.</p></div>${editable?'<div class="hd-actions"><button class="btn" data-hd="link-mail">Link email</button><button class="btn" data-hd="draft">Prepare reply draft</button></div>':''}</div><div class="hd-conversation">${t.messages.map(m=>`<article class="hd-message ${m.visibility==='internal'?'is-internal':''}"><header><strong>${esc(m.by||'Team')}</strong><span>${m.visibility==='internal'?'Internal note':m.direction==='incoming'?'Client message':'Sent externally · recorded'} · ${date(m.at)}</span></header><p>${esc(m.text)}</p>${m.sourceMessageId?`<button class="row-action" data-hd="source-mail" data-id="${esc(m.sourceMessageId)}">Open original email ↗</button>`:''}</article>`).join('')||'<p class="hd-hint">No conversation recorded yet.</p>'}</div>${editable?`<form id="hd-message-form" data-revision="${t.revision||1}">${choice('direction','Message type',[['internal','Internal note'],['incoming','Record client reply'],['outgoing','Record response already sent']], 'internal')}${area('text','Message','',true)}<label class="hd-check"><input type="checkbox" name="sentConfirmed">For an outgoing response: I confirm it was already sent outside this CRM.</label>${errorHtml}<button class="btn btn-primary" type="submit">Save entry</button><p class="hd-hint">Saving here does not send an email. A saved draft does not stop the response clock.</p></form>`:''}</section>
  <section class="card hd-section"><div class="card-head"><div><h2>Attachments</h2><p>Case evidence · ${(t.attachments||[]).length} files</p></div></div><div class="hd-files">${(t.attachments||[]).map(f=>`<div><span><strong>${esc(f.name)}</strong><small>${Math.ceil(f.size/1000)} KB · ${esc(f.visibility==='client'?'Client correspondence':'Internal')} · ${date(f.at)}</small></span><button class="row-action" data-hd="download" data-id="${esc(f.id)}">Download</button>${editable?`<button class="row-action" data-hd="remove-file" data-id="${esc(f.id)}">Remove</button>`:''}</div>`).join('')||'<p class="hd-hint">Add screenshots, logs or supporting documents.</p>'}</div>${editable?`<form id="hd-file-form" data-revision="${t.revision||1}"><div class="field"><label for="hd-files">Add files (750 KB each; 2 MB per case)</label><input id="hd-files" type="file" name="files" multiple required accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.csv,.docx,.xlsx,.log"></div>${choice('visibility','Attachment context',[['internal','Internal evidence'],['client','Client correspondence']], 'internal')}${errorHtml}<button class="btn" type="submit">Attach files</button></form>`:''}</section></div>
  <aside class="hd-stack">${editable?`<section class="card hd-section"><h2>Next action</h2><form id="hd-status-form" data-revision="${t.revision||1}">${choice('status','Status',next,t.status)}${choice('ownerId','Assigned owner',owners,t.ownerId||'')}${choice('priority','Priority',H.priorities,t.priority)}${area('note','Update / resolution / reopening reason','',true)}<div id="hd-close-fields" hidden>${choice('closure','Closure method',[['','Choose confirmation'],['Client confirmed','Client confirmed'],['No-response policy','No-response policy']], '')}${input('confirmedBy','Confirmed by (name / reference)')}<p class="hd-hint">No-response closure requires ${t.serviceRules.closeAfter/60} working hours after a recorded resolution response, with no later client reply.</p></div>${errorHtml}<button class="btn btn-primary" type="submit">Save update</button></form></section>`:'<section class="card hd-section"><h2>Archived case</h2><p>Conversation, files and history are retained. Restore the case to work on it again.</p></section>'}<section class="card hd-section"><h2>Activity history</h2><div class="hd-history">${[...t.history].reverse().map(h=>`<article><strong>${esc(h.by||'Legacy record')}</strong><small>${/^\d{4}-\d\d-\d\dT/.test(h.at||'')?date(h.at):esc(h.at||'')}</small><p>${esc(h.text)}</p>${h.changes?`<details><summary>Changed fields</summary>${Object.entries(h.changes).map(([k,v])=>`<p><strong>${esc(k)}</strong>: ${esc(typeof v.from==='object'?JSON.stringify(v.from):v.from)} → ${esc(typeof v.to==='object'?JSON.stringify(v.to):v.to)}</p>`).join('')}</details>`:''}</article>`).join('')}</div></section></aside></div></div>`;
 };

 window.helpdeskFromMail=function(messageId){
  const message=byId('messages',messageId);if(!message?.clientId){toast('Link this email to a client first.');return;}
  const existing=H.linkedCase(state,message);
  if(existing){
   if(!existing.sourceMessageIds.includes(message.id)){
    try{commit(()=>H.linkMail(state,existing.id,message.id));}catch(error){toast(error.message);}
   }
   openCase(existing.id);return;
  }
  const plan=inboxReplyPlan(message);openHelpdeskForm('',{clientId:message.clientId,branchId:plan.branch?.id||'',subject:message.subject,description:message.body||message.snippet,source:'Email',sourceMessageId:message.id,requester:{name:message.from,email:message.email,phone:''}});
 };
 function archiveForm(restore=false){const t=byId('tickets',selectedTicketId);if(!t)return;if(!restore&&!['Closed','Cancelled'].includes(t.status)){toast('Close or cancel the case first. Its history will be retained in the archive.');return;}modal(restore?'Restore case':'Archive case',`${t.number} · ${t.subject}`,`<form id="hd-archive-form" data-id="${esc(t.id)}" data-restore="${restore}">${area('reason','Reason','',true)}${errorHtml}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit" form="hd-archive-form">${restore?'Restore':'Archive'}</button>`);}
 function settings(){
  const r=state.helpdesk.rules;
  modal('Helpdesk settings','Workspace service targets apply to new cases. Existing cases retain their saved policy.',`<form id="hd-settings-form"><h3>Working calendar · India time (IST)</h3><div class="form-grid">${input('start','Start hour (0–23)',r.calendar.start,'number',true)}${input('end','End hour (1–24)',r.calendar.end,'number',true)}</div><fieldset class="hd-days"><legend>Working days</legend>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((day,i)=>`<label><input type="checkbox" name="days" value="${i}" ${r.calendar.days.includes(i)?'checked':''}>${day}</label>`).join('')}</fieldset>${area('holidays','Holidays (YYYY-MM-DD, one per line)',r.calendar.holidays.join('\n'))}<h3>Service targets · working hours</h3>${H.priorities.map(p=>`<div class="form-grid">${input(p+'Response',p+' first response',r.targets[p].response/60,'number',true)}${input(p+'Resolution',p+' resolution',r.targets[p].resolution/60,'number',true)}</div>`).join('')}<label class="hd-check"><input type="checkbox" name="pauseOnClient" ${r.pauseOnClient?'checked':''}>Pause resolution while waiting on client (response clock continues)</label>${input('closeAfter','No-response closure wait · working hours',r.closeAfter/60,'number',true)}<h3>Assignment directory</h3><p class="hd-hint">The operator in this preview is IDSSPL Demo. Team records support assignment; they do not create sign-in accounts.</p>${state.supportUsers.map(u=>`<div class="hd-user-row" data-user="${esc(u.id)}"><input aria-label="Member name" name="userName-${esc(u.id)}" value="${esc(u.name)}" ${u.id==='support-demo'?'readonly':''} required><input aria-label="Team" name="userTeam-${esc(u.id)}" value="${esc(u.team)}" required><label><input type="checkbox" name="userActive-${esc(u.id)}" ${u.active?'checked':''} ${u.id==='support-demo'?'disabled':''}>Active</label></div>`).join('')}<div class="form-grid">${input('newName','Add team member (optional)')}${input('newTeam','Team','Support')}</div>${errorHtml}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit" form="hd-settings-form">Save settings</button>`);$('.modal').classList.add('hd-modal');
 }
 const originalOpenForm=openForm;openForm=function(type){return type==='ticket'?openHelpdeskForm():originalOpenForm(type);};
 openTicketDetailsEditor=id=>openHelpdeskForm(id);
 const originalDelete=openRecordDelete;openRecordDelete=function(kind,id){if(kind==='ticket'){selectedTicketId=id;archiveForm();return;}if((kind==='mail')&&state.tickets.some(t=>t.sourceMessageIds.includes(id))){toast('This email is evidence for a support case. Archive the email to keep its case link.');return;}return originalDelete(kind,id);};
 const originalDeleteRecord=deleteRecord;deleteRecord=function(kind,id){if(kind==='ticket')throw new Error('Support cases must be archived, not permanently deleted.');if(kind==='mail'&&state.tickets.some(t=>t.sourceMessageIds.includes(id))){toast('Keep the original email linked to its support case.');return;}return originalDeleteRecord(kind,id);};
 const originalDetail=showDetail;showDetail=function(type,id){if(type==='ticket')return openCase(id);return originalDetail(type,id);};
 const originalSettings=renderSettings;renderSettings=function(){return `<section class="card hd-section"><div class="card-head"><div><h2>Helpdesk team & service rules</h2><p>Working hours, targets, holidays and assignment directory.</p></div><button class="btn" data-hd="settings">Manage Helpdesk</button></div></section>`+originalSettings();};
 const originalInbox=renderInbox;renderInbox=function(){let html=originalInbox();const message=byId('messages',selectedMail),draft=byId('mailDrafts',selectedMail),linked=message?H.linkedCase(state,message):draft?.caseId?byId('tickets',draft.caseId):null;if(linked){html=html.replace('Create support case ↗',`Open ${esc(linked.number)} ↗`);html=html.replace('<div class="mail-reader-footer">',`<div class="hd-resolution"><strong>Support case ${esc(linked.number)}</strong><p>${esc(linked.subject)} · ${esc(linked.archivedAt?'Archived':linked.status)}</p><button class="row-action" data-ticket="${esc(linked.id)}">Open case ↗</button></div><div class="mail-reader-footer">`);}return html;};
 const originalProfile=renderProfile;renderProfile=function(){const html=originalProfile();if(profileTab!=='overview')return html;const cases=state.tickets.filter(t=>t.clientId===selectedClientId);return html+`<section class="card hd-section hd-profile-cases"><div class="card-head"><div><h2>Support cases</h2><p>${cases.filter(H.active).length} active · ${cases.length} total, including archived history</p></div><button class="btn" data-action="add-ticket">New case</button></div>${cases.map(t=>`<button class="hd-profile-case" data-ticket="${esc(t.id)}"><span><strong>${esc(t.number)} · ${esc(t.subject)}</strong><small>${esc(scopeLabel(t))} · ${esc(t.owner)}</small></span>${statusPill(t)}</button>`).join('')||'<p class="hd-hint">No support cases yet.</p>'}</section>`;};

 document.addEventListener('change',e=>{
  const form=e.target.closest('#hd-case-form');if(form){if(e.target.name==='clientId'){form.querySelectorAll('[name="branchIds"]').forEach(el=>el.checked=false);form.elements.productId.value='';const c=byId('clients',e.target.value);form.elements.requesterName.value=c?.contact||'';form.elements.requesterEmail.value=c?.email||'';form.elements.requesterPhone.value=c?.phone||'';}if(['clientId','scope','productId','branchIds'].includes(e.target.name))rebuildContext(form);}
  if(e.target.closest('#hd-status-form')&&e.target.name==='status')$('#hd-close-fields').hidden=e.target.value!=='Closed';
 });
 window.addEventListener('storage',e=>{
  if(e.key!==STORE_KEY||!e.newValue)return;
  try{const updated=JSON.parse(e.newValue);if(!Array.isArray(updated.tickets))return;if(document.querySelector('.modal form')||document.activeElement?.closest('form')){externalChange=true;toast('Another tab changed this workspace. Reload before saving your open form.');return;}state=H.normalize(updated);externalChange=false;if(['helpdesk','ticketDetail','profile','inbox'].includes(view))render();}catch{toast('Could not load a workspace update. Reload before making changes.');externalChange=true;}
 });
 document.addEventListener('click',e=>{
  const resolve=e.target.closest('[data-action="resolve-ticket"]');if(resolve){e.preventDefault();e.stopImmediatePropagation();openCase(resolve.dataset.id);toast('Record the resolution in Next action.');return;}
  const el=e.target.closest('[data-hd]');if(!el)return;const action=el.dataset.hd,t=byId('tickets',selectedTicketId);
  if(action==='queue'){queue=el.dataset.value;page=1;render();}
  if(action==='prev'){page--;render();}if(action==='next'){page++;render();}
  if(action==='settings')settings();if(action==='archive')archiveForm();if(action==='restore')archiveForm(true);
  if(action==='link-mail'){const messages=state.messages.filter(m=>m.clientId===t.clientId&&!t.sourceMessageIds.includes(m.id)&&(!H.linkedCase(state,m)||H.linkedCase(state,m).id===t.id));modal('Link client email',`${t.number} · ${t.requester.name}`,`<form id="hd-link-mail-form" data-case="${esc(t.id)}">${choice('messageId','Client email',[['','Choose an email'],...messages.map(m=>[m.id,`${m.subject} · ${m.from||m.email}`])],'')}<p class="hd-hint">The message and supported attachments will be captured here. A client follow-up resumes a waiting case or reopens a resolved case.</p>${errorHtml}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit" form="hd-link-mail-form">Link email</button>`);}
  if(action==='source-mail'){const m=byId('messages',el.dataset.id);if(!m){toast('Original email is unavailable. The captured message remains in case history.');return;}selectedMail=m.id;mailFolder=m.archived?'Archive':'Inbox';mailClientFilter='all';mailFilter='All';filter='';setView('inbox');}
  if(action==='draft'){
   if(!t.requester.email){toast('Add the requester’s email in Edit details first.');return;}
   const body=`Hello ${t.requester.name||'team'},\n\nRegarding ${t.number}: ${t.subject}.\n\n${t.status==='Resolved'?t.resolution:'We are reviewing your request. [Add the verified update, next step and expected follow-up.]'}\n\nRegards,\nIDSSPL Support`;
   openMailComposer(t.sourceMessageIds[0]||'','',{to:t.requester.email,subject:`[${t.number}] ${t.subject}`,body,clientId:t.clientId});const form=$('#mail-compose-form');if(form)form.dataset.caseId=t.id;
  }
  if(action==='download'){const file=t.attachments.find(f=>f.id===el.dataset.id);if(!file?.dataUrl){toast('File is unavailable.');return;}const a=document.createElement('a');a.href=file.dataUrl;a.download=file.name;document.body.append(a);a.click();a.remove();}
  if(action==='remove-file'){const file=t.attachments.find(f=>f.id===el.dataset.id);if(!file)return;modal('Remove attachment',file.name,`<form id="hd-remove-file-form" data-file="${esc(file.id)}" data-case="${esc(t.id)}">${area('reason','Reason for removing this file','',true)}${errorHtml}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-danger" type="submit" form="hd-remove-file-form">Remove file</button>`);}
 },true);
 document.addEventListener('submit',async e=>{
  const form=e.target;if(!form.id.startsWith('hd-'))return;e.preventDefault();e.stopImmediatePropagation();if(form.dataset.busy)return;
  form.dataset.busy='true';const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
  const data=Object.fromEntries(new FormData(form));
  try{
   if(form.id==='hd-filter-form'){search=data.search;clientFilter=data.clientFilter;ownerFilter=data.ownerFilter;page=1;render();}
   if(form.id==='hd-case-form'){const inputData=formData(form);inputData.id=uid('ticket');const t=commit(()=>form.dataset.id?H.edit(state,form.dataset.id,inputData):H.create(state,inputData));$('#modal-root').innerHTML='';openCase(t.id);toast(form.dataset.id?'Case details updated.':'Support case created.');}
   if(form.id==='hd-status-form'){commit(()=>H.transition(state,selectedTicketId,{...data,revision:form.dataset.revision}));refresh('Case updated.');}
   if(form.id==='hd-message-form'){commit(()=>H.addMessage(state,selectedTicketId,{...data,id:uid('hm'),sentConfirmed:!!data.sentConfirmed,revision:form.dataset.revision}));refresh('Entry recorded.');}
   if(form.id==='hd-archive-form'){commit(()=>H.archive(state,form.dataset.id,data.reason,form.dataset.restore==='true'));refresh('Case history retained.');}
   if(form.id==='hd-link-mail-form'){commit(()=>H.linkMail(state,form.dataset.case,data.messageId));refresh('Client email linked.');}
   if(form.id==='hd-remove-file-form'){commit(()=>{const t=byId('tickets',form.dataset.case);if(!t||t.archivedAt)throw new Error('Restore the case before removing attachments.');if(!data.reason.trim())throw new Error('Add a reason.');const f=t.attachments.find(f=>f.id===form.dataset.file);if(!f)throw new Error('Attachment already removed.');t.attachments=t.attachments.filter(f=>f.id!==form.dataset.file);t.revision=(t.revision||1)+1;H.stamp(t,H.actor(state),`Attachment removed: ${f.name}. ${data.reason.trim()}`,Date.now(),'attachment');});refresh('Attachment removed; removal recorded in history.');}
   if(form.id==='hd-file-form'){
    const caseId=selectedTicketId,files=[...form.elements.files.files];if(!files.length)throw new Error('Choose a file.');files.forEach(H.validateAttachment);
    const read=await Promise.all(files.map(async file=>({id:uid('hf'),name:file.name,size:file.size,type:file.type,dataUrl:await readFileAsDataUrl(file),visibility:data.visibility,at:new Date().toISOString()})));
    commit(()=>{const t=byId('tickets',caseId);if(!t||t.archivedAt||Number(t.revision||1)!==Number(form.dataset.revision))throw new Error('This case changed. Review it before uploading again.');if(t.attachments.length+read.length>10||[...t.attachments,...read].reduce((n,f)=>n+f.size,0)>2000000)throw new Error('Use up to 10 files and 2 MB total per case.');if(read.some(f=>t.attachments.some(old=>old.name===f.name&&old.size===f.size)))throw new Error('A matching file is already attached.');t.attachments.push(...read);t.revision=(t.revision||1)+1;H.stamp(t,H.actor(state),'Attachments added: '+read.map(f=>f.name).join(', '),Date.now(),'attachment');});refresh('Files attached.');
   }
   if(form.id==='hd-settings-form'){
    commit(()=>{
     const rules=H.defaults(),start=Number(data.start),end=Number(data.end),days=new FormData(form).getAll('days').map(Number),holidays=data.holidays.split(/\s+/).filter(Boolean);
     if(!Number.isInteger(start)||!Number.isInteger(end)||start<0||end>24||end<=start||!days.length)throw new Error('Choose working days and valid start/end hours.');
     if(holidays.some(d=>!/^\d{4}-\d\d-\d\d$/.test(d)||!Number.isFinite(Date.parse(d))||new Date(d).toISOString().slice(0,10)!==d))throw new Error('Enter valid holiday dates in YYYY-MM-DD format.');
     rules.calendar={offset:330,start,end,days,holidays:[...new Set(holidays)]};
     for(const p of H.priorities){const response=Number(data[p+'Response']),resolution=Number(data[p+'Resolution']);if(!(response>0&&resolution>=response&&resolution<=8760))throw new Error('Targets must be positive; resolution must allow at least the response time (max 8,760 hours).');rules.targets[p]={response:response*60,resolution:resolution*60};}
     rules.pauseOnClient=!!data.pauseOnClient;rules.closeAfter=Number(data.closeAfter)*60;if(!(rules.closeAfter>=60&&rules.closeAfter<=525600))throw new Error('Set a no-response wait between 1 and 8,760 working hours.');
     for(const u of state.supportUsers){const name=(data['userName-'+u.id]||'').trim(),team=(data['userTeam-'+u.id]||'').trim(),enabled=u.id==='support-demo'||!!data['userActive-'+u.id];if(!name||!team)throw new Error('Each member needs a name and team.');if(!enabled&&state.tickets.some(t=>H.active(t)&&t.ownerId===u.id))throw new Error(`Reassign ${u.name}’s active cases before deactivating them.`);u.name=name;u.team=team;u.active=enabled;}
     if(data.newName.trim()){if(state.supportUsers.some(u=>u.name.toLowerCase()===data.newName.trim().toLowerCase()))throw new Error('This team member already exists.');state.supportUsers.push({id:uid('support'),name:data.newName.trim(),team:data.newTeam.trim()||'Support',active:true});}
     state.helpdesk.rules=rules;(state.helpdesk.settingsHistory ||= []).push({at:new Date().toISOString(),by:H.actor(state).name,rules});
    });refresh('Helpdesk settings saved for new cases.');
   }
  }catch(error){feedback(error,form);}finally{delete form.dataset.busy;if(submit?.isConnected)submit.disabled=false;}
 },true);
 // Preserve a draft's case link without treating a draft as a sent response.
 const originalSaveDraft=saveMailDraft;saveMailDraft=function(e){const caseId=e.target.dataset.caseId;originalSaveDraft(e);if(caseId&&view==='inbox'&&mailFolder==='Drafts'){try{commit(()=>{const draft=byId('mailDrafts',selectedMail);if(draft)draft.caseId=caseId;});}catch(error){toast(error.message);}}};
 setInterval(()=>{if(document.visibilityState==='visible'&&view==='helpdesk'&&!$('#modal-root').children.length&&!document.activeElement?.closest('form'))render();},60000);
 const preview=new URLSearchParams(location.search).get('preview');
 // Preview links may intentionally open Helpdesk, but a normal refresh always returns to Overview.
 if(preview?.startsWith('helpdesk-'))setView('helpdesk');
 else if(preview==='admin-panel'||preview==='home'||view==='helpdesk'||view==='ticketDetail')setView('overview');
})();
